/* xx_qcow_extractor.c - search raw data for QCOW.
 *
 * Scans for:
 *   51 46 49 FB 00 00 00 02 at +0  ("QFI.....")
 *   51 46 49 FB 00 00 00 03 at +0  ("QFI.....")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the qcow reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/qcow/xx_qcow.h"

static const uint8_t k_anchor0[] = { 0x51, 0x46, 0x49, 0xFB, 0x00, 0x00, 0x00, 0x02 };
static const uint8_t k_anchor1[] = { 0x51, 0x46, 0x49, 0xFB, 0x00, 0x00, 0x00, 0x03 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_QCOW };

static Abstractformat *xx_qcow_search_open(xx_io_device *window) {
    xx_qcow *reader = xx_qcow_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_qcow_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_qcow_free((xx_qcow *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_qcow_search_open, xx_qcow_search_close
};

static xx_format_search_state *xx_qcow_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_qcow_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_qcow_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_qcow_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_qcow_extractor = {
    xx_qcow_create_format_search,
    xx_qcow_get_current_format_info,
    xx_qcow_format_search_find_next,
    xx_qcow_free_format_search
};
